// Example: Use MCP tools via code execution pattern
// This reduces token consumption by loading tools on-demand

// Instead of loading all 39 tool definitions, we:
// 1. Search for relevant tools first (progressive disclosure)
// 2. Load only what we need
// 3. Process data before returning to model

const mcp = require('@n8n/mcp-client');

// Progressive disclosure: search for workflow tools
const workflowTools = await mcp.callTool('n8n-automation', 'search_tools', {
  query: 'workflow',
  detailLevel: 'description'
});

console.log(`Found ${workflowTools.length} workflow-related tools`);

// Use the tools we found
const workflows = await mcp.callTool('n8n-automation', 'workflows.list', {
  limit: 100
});

// Process data in code (not in model context)
const activeWorkflows = workflows.filter(w => w.active === true);
const brokenWorkflows = workflows.filter(w => w.errorCount > 0);

// Only return summary, not all data
return {
  total: workflows.length,
  active: activeWorkflows.length,
  broken: brokenWorkflows.length,
  brokenNames: brokenWorkflows.slice(0, 5).map(w => w.name)
};
